.a748-shell{margin:20px 0 25px}.a748-shell,.a748-shell *{box-sizing:border-box}.a748-shell .a748-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.8fr);gap:18px}.a748-shell .a748-body{padding:19px 21px}.a748-shell .a748-title{margin:0;color:#17284f;font-size:15px;line-height:1.4}.a748-shell .a748-caption{font-size:11px;color:#7b8799;margin:5px 0 0;line-height:1.6}.a748-shell .a748-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.a748-shell .a748-strong{color:#17284f;font-weight:700}.a748-shell .a748-badge{display:inline-flex;align-items:center;border:1px solid #d6eae5;background:#edf8f4;color:#167d70;padding:5px 10px;border-radius:99px;font-size:11px;font-weight:700}.a748-shell .a748-badge.muted{border-color:#e0e5ed;background:#f7f9fc;color:#65768e}.a748-shell .a748-member-list,.a748-shell .a748-timeline{list-style:none;padding:0;margin:12px 0;display:grid;gap:10px}.a748-shell .a748-member,.a748-shell .a748-entry{padding:13px 15px;border:1px solid #e5eaf1;border-radius:10px;background:#fbfcfe}.a748-shell .a748-member{display:flex;justify-content:space-between;gap:10px;align-items:center}.a748-shell .a748-member small,.a748-shell .a748-entry small{display:block;font-size:10px;color:#8390a0;margin-top:4px}.a748-shell .a748-entry-head{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.a748-shell .a748-entry p{margin:11px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;color:#42516b;font-size:12px;line-height:1.7}.a748-shell .a748-form{display:grid;gap:11px}.a748-shell .a748-form label{font-size:11px;font-weight:700;color:#5d6d85}.a748-shell .a748-form textarea,.a748-shell .a748-form input,.a748-shell .a748-form select{width:100%;min-height:41px;padding:10px 12px;border:1px solid #dce4ed;border-radius:8px;background:#fff;color:#25334d;font:inherit;font-size:12px}.a748-shell .a748-form textarea{min-height:95px;resize:vertical}.a748-shell .a748-form textarea:focus,.a748-shell .a748-form input:focus,.a748-shell .a748-form select:focus